/**
 * Phase 0, DoD 0.3 — tool-class census across every committed corpus.
 *
 * THROWAWAY SPIKE CODE. It is frozen at the phase close and never imported by
 * `src/`. It imports only `node:` builtins, deliberately: the census is
 * evidence about the corpora, and evidence produced by the code under test is
 * not evidence. `scripts/opencode-golden.mjs` is the precedent.
 *
 * WHAT IT ANSWERS. For every distinct tool name in every corpus: which engine
 * wrote it, how many times it was called, whether the call carries a
 * STRUCTURED input object at all, and which key of that object holds a
 * filesystem path. Phase 1 generates `src/stats/toolclass.ts` from this table
 * rather than from memory.
 *
 * WHY "structured" is its own column and not an implementation detail. Codex's
 * `exec` is a `custom_tool_call` whose `input` is a STRING of JavaScript, not
 * an object. A census that assumed every tool call has an input object would
 * report `exec` as "no file argument" and be right by accident, for the wrong
 * reason, and would break the moment a string-input tool did name a file. The
 * three states are distinct and all three are reported: no input, string
 * input, object input.
 *
 * Usage:
 *   node lab/spike/stats/toolclass-census.mjs            # writes the report
 *   node lab/spike/stats/toolclass-census.mjs --stdout   # prints instead
 */
import { readFileSync, readdirSync, existsSync, writeFileSync, mkdirSync, statSync } from 'node:fs';
import { join, basename } from 'node:path';
import { DatabaseSync } from 'node:sqlite';

const FIXTURES = 'fixtures';
const OUT_DIR = 'docs/evidence/phase-0-stats';

/**
 * The three provenance anchors, re-measured from the fingerprint modules
 * rather than written down here. A corpus name is not an anchor because it
 * looks like one; it is an anchor because a fingerprint pins it.
 */
function readAnchors() {
  const read = (path, symbol) => {
    const src = readFileSync(path, 'utf8');
    const m = src.match(new RegExp(`${symbol}\\s*=\\s*'([^']+)'`));
    if (!m) throw new Error(`could not re-measure ${symbol} from ${path}`);
    return m[1];
  };
  return {
    cc: `cc-${read('src/parser/fingerprint.ts', 'PINNED_CC_VERSION')}`,
    opencode: `opencode-${read('src/opencode/fingerprint.ts', 'PINNED_OPENCODE_VERSION')}`,
    codex: `codex-${read('src/codex/fingerprint.ts', 'PINNED_CODEX_VERSION')}`,
  };
}

const walk = (dir) =>
  readdirSync(dir, { withFileTypes: true }).flatMap((e) =>
    e.isDirectory() ? walk(join(dir, e.name)) : [join(dir, e.name)],
  );

/**
 * Which engine wrote a corpus, decided by STRUCTURE rather than by the
 * directory's name. A corpus directory is not identified by its name — this
 * repository has a recorded case of a capture directory whose name outlived
 * its contents.
 */
function classifyCorpus(dir) {
  if (existsSync(join(dir, 'opencode.db'))) return 'opencode';
  if (existsSync(join(dir, 'projects'))) return 'cc';
  const jsonl = walk(dir).filter((p) => p.endsWith('.jsonl') && !p.includes('hook-stream'));
  for (const p of jsonl.slice(0, 4)) {
    const head = readFileSync(p, 'utf8').split('\n', 1)[0] ?? '';
    if (head.includes('"payload"')) return 'codex';
  }
  return null;
}

