  it('is the last section, so nothing later can quietly contradict it', () => {
    expect((SPEC ?? '').indexOf(AMENDMENT_HEADING)).toBe((SPEC ?? '').lastIndexOf(AMENDMENT_HEADING));
    expect(amendment.includes('\n## ')).toBe(false);
  });

